                "used_for": "incremental utility evaluation",
                "evaluation_only": "yes",
            },
            {
                "field_name": str(ScoreCol.CLASSIFICATION_SCORE),
                "business_meaning": "Predicted residual issue probability",
                "type_or_category": "model score",
                "privacy_sensitivity": "Low",
